const items = $input.all();
const results = [];

const DEFAULT_STAGE_WEIGHTS = { 1: 0.10, 2: 0.35, 3: 0.60, 4: 0.85, 5: 0.95, 6: 1.00, 7: 0.00 };
const DEFAULT_STAGE_NAMES = { 1: 'Новый лид', 2: 'Квалификация', 3: 'Встреча / Демо', 4: 'КП / В работе', 5: 'Финальный счёт / Договор', 6: 'Успешно реализовано', 7: 'Закрыто и не реализовано' };
const MAX_SHEET_CELL_CHARS = 45000;

function parseNumericPrice(val) {
  if (val === null || val === undefined || val === '') return [0.0, true];
  if (typeof val === 'number') return [Number.isFinite(val) ? val : 0.0, false];
  let clean = String(val).trim().replace(/[^\d.,]/g, '');
  if (!clean) return [0.0, true];
  if (clean.includes(',') && clean.includes('.')) {
    if (clean.lastIndexOf(',') > clean.lastIndexOf('.')) clean = clean.replace(/\./g, '').replace(',', '.');
    else clean = clean.replace(/,/g, '');
  } else if (clean.includes(',')) {
    if (/,\d{3}$/.test(clean) || (clean.match(/,/g) || []).length > 1) clean = clean.replace(/,/g, '');
    else clean = clean.replace(',', '.');
  } else if (clean.includes('.')) {
    if (/\.\d{3}$/.test(clean) || (clean.match(/\./g) || []).length > 1) clean = clean.replace(/\./g, '');
  }
  const parsed = parseFloat(clean);
  return (Number.isNaN(parsed) || !Number.isFinite(parsed)) ? [0.0, true] : [parsed, false];
}

function sanitizeCustomPayload(payload) {
  if (!payload || typeof payload !== 'object') return '{}';
  try {
    const raw = JSON.stringify(payload);
    if (raw.length > MAX_SHEET_CELL_CHARS) return raw.slice(0, MAX_SHEET_CELL_CHARS - 30) + '..."_truncated":true}';
    return raw;
  } catch { return '{}'; }
}

for (const item of items) {
  const raw = item.json || item;
  const payload = raw.body || raw;
  const tenantId = raw.tenant_id || payload.tenant_id || 'TNT-001';
  const spreadsheetId = raw.spreadsheet_id || payload.spreadsheet_id || '';
  const source = String(raw.source || payload.source || (payload.pipeline_id !== undefined ? 'amocrm' : 'bitrix24')).toLowerCase();

  if (source.includes('amo')) {
    const rawId = String(payload.id || payload.ID || '').trim();
    if (!rawId) continue;
    const dealId = rawId.startsWith('AMO-') ? rawId : `AMO-${rawId}`;
    const title = String(payload.name || payload.title || `Сделка #${rawId}`).trim();
    const [amount, isPriceUnknown] = parseNumericPrice(payload.price ?? payload.amount);
    const statusStr = String(payload.status_id || '').trim();
    let stageNum = null, stageName = `Статус ${statusStr}`, weight = null, isWon = false, isLost = false, isActive = false, status = 'UNKNOWN';
    if (statusStr === '142') { stageNum = 6; stageName = 'Успешно реализовано'; weight = 1.0; isWon = true; status = 'WON'; }
    else if (statusStr === '143') { stageNum = 7; stageName = 'Закрыто и не реализовано'; weight = 0.0; isLost = true; status = 'LOST'; }
    else if (statusStr === '1') { stageNum = 1; stageName = 'Новый лид'; weight = 0.10; isActive = true; status = 'ACTIVE'; }
    else { stageNum = 2; stageName = 'В работе'; weight = 0.35; isActive = true; status = 'ACTIVE'; }
    let weightedAmount = (weight !== null && !Number.isNaN(weight)) ? Math.round(amount * weight * 100) / 100 : null;
    const isDeleted = Boolean(payload.is_deleted || status === 'DELETED');
    results.push({
      json: {
        deal_id: dealId,
        company_name: title,
        amount,
        amount_str: `${Math.round(amount).toLocaleString('ru-RU')} ₽`,
        price_is_unknown: isPriceUnknown,
        stage_id: stageNum !== null ? String(stageNum) : '0',
        stage_name: stageName,
        created_at: new Date().toISOString().slice(0, 10),
        updated_at: new Date().toISOString().slice(0, 10),
        responsible_user: String(payload.responsible_user_id || payload.responsible_user || ''),
        manager_name: payload.manager_name || (payload.responsible_user_id ? `Менеджер #${payload.responsible_user_id}` : 'Не назначен'),
        segment: 'General B2B',
        source: 'amoCRM',
        client_id: rawId.replace('AMO-', ''),
        client_grade: amount >= 300000 ? 'A' : (amount >= 150000 ? 'B' : 'C'),
        lost_reason: isLost ? 'Отказ' : (isDeleted ? 'Удалена в CRM' : ''),
        is_won: isWon ? '1' : '0',
        is_lost: isLost || isDeleted ? '1' : '0',
        is_active: isActive && !isDeleted ? '1' : '0',
        weighted_amount: weightedAmount,
        weighted_amount_str: weightedAmount !== null ? `${Math.round(weightedAmount).toLocaleString('ru-RU')} ₽` : '—',
        status: isDeleted ? 'DELETED' : status,
        is_deleted: isDeleted ? '1' : '0',
        custom_payload: sanitizeCustomPayload(payload.custom_fields_values || payload.custom_fields || {}),
        channel: 'amocrm',
        synced_at: new Date().toISOString(),
        tenant_id: tenantId,
        spreadsheet_id: spreadsheetId
      }
    });
  } else {
    const d = payload.FIELDS || payload.fields || payload;
    const rawId = String(d.ID || d.id || '').trim();
    if (!rawId) continue;
    const dealId = rawId.startsWith('B24-') ? rawId : `B24-${rawId}`;
    const title = String(d.TITLE || d.title || `Сделка #${rawId}`).trim();
    const [amount, isPriceUnknown] = parseNumericPrice(d.OPPORTUNITY ?? d.opportunity ?? d.price);
    const b24Stage = String(d.STAGE_ID || d.stage_id || '').toUpperCase();
    let stageNum = 1, stageName = 'Новая', weight = 0.10, isWon = false, isLost = false, isActive = true, status = 'ACTIVE';
    if (b24Stage.includes('WON') || b24Stage.includes('УСПЕШНО')) { stageNum = 6; stageName = 'Успешно реализовано'; weight = 1.0; isWon = true; isActive = false; status = 'WON'; }
    else if (b24Stage.includes('LOSE') || b24Stage.includes('LOST') || b24Stage.includes('ПРОВАЛ')) { stageNum = 7; stageName = 'Закрыто и не реализовано'; weight = 0.0; isLost = true; isActive = false; status = 'LOST'; }
    else if (b24Stage.includes('PREPAYMENT')) { stageNum = 3; stageName = 'Счёт на предоплату'; weight = 0.60; }
    else if (b24Stage.includes('PREPARATION')) { stageNum = 2; stageName = 'Подготовка документов'; weight = 0.35; }
    else if (b24Stage.includes('EXECUTING')) { stageNum = 4; stageName = 'В работе'; weight = 0.85; }
    else if (b24Stage.includes('FINAL')) { stageNum = 5; stageName = 'Финальный счёт'; weight = 0.95; }
    let weightedAmount = (weight !== null && !Number.isNaN(weight)) ? Math.round(amount * weight * 100) / 100 : null;
    const isDeleted = Boolean(d.is_deleted || status === 'DELETED');
    results.push({
      json: {
        deal_id: dealId,
        company_name: title,
        amount,
        amount_str: `${Math.round(amount).toLocaleString('ru-RU')} ₽`,
        price_is_unknown: isPriceUnknown,
        stage_id: String(stageNum),
        stage_name: stageName,
        created_at: String(d.DATE_CREATE || new Date().toISOString()).slice(0, 10),
        updated_at: String(d.DATE_MODIFY || new Date().toISOString()).slice(0, 10),
        responsible_user: String(d.ASSIGNED_BY_ID || d.assigned_by_id || ''),
        manager_name: d.manager_name || (d.ASSIGNED_BY_ID ? `Менеджер #${d.ASSIGNED_BY_ID}` : 'Не назначен'),
        segment: 'General B2B',
        source: 'Bitrix24',
        client_id: rawId.replace('B24-', ''),
        client_grade: amount >= 300000 ? 'A' : (amount >= 150000 ? 'B' : 'C'),
        lost_reason: isLost ? 'Отказ' : (isDeleted ? 'Удалена в CRM' : ''),
        is_won: isWon ? '1' : '0',
        is_lost: isLost || isDeleted ? '1' : '0',
        is_active: isActive && !isDeleted ? '1' : '0',
        weighted_amount: weightedAmount,
        weighted_amount_str: weightedAmount !== null ? `${Math.round(weightedAmount).toLocaleString('ru-RU')} ₽` : '—',
        status: isDeleted ? 'DELETED' : status,
        is_deleted: isDeleted ? '1' : '0',
        custom_payload: sanitizeCustomPayload(d),
        channel: 'bitrix24',
        synced_at: new Date().toISOString(),
        tenant_id: tenantId,
        spreadsheet_id: spreadsheetId
      }
    });
  }
}

return results;
